<script setup>
import {ref,computed} from 'vue';import {money,cents,can,fieldAccess,approvalStage,approvalStageLabel} from './domain.js';import {extRows,extStatus,extensionFields,referenceRows,pricingTotals,dueDate,canExtensionAct,demandBalance,corporateBalance} from './payment-schedules.js';import {suiteRows} from './vendor-suite.js';import {financeStatus} from './finance.js';import MetaFields from './MetaFields.vue';
const p=defineProps(['state','user','tenantId','page','execute','busy','failure']);const dialog=ref(''),form=ref({}),error=ref(''),selected=ref(''),showProfile=ref(null),printDemand=ref(null),activeTab=ref('schedule');
const rows=k=>extRows(p.state,k,p.tenantId),allowed=(a,k)=>can(p.state,p.user,p.tenantId,a,k),editable=k=>allowed('create',k)&&extensionFields[k].every(f=>fieldAccess(p.state,p.user,p.tenantId,f,k)==='edit');const sales=computed(()=>suiteRows(p.state,'sale',p.tenantId).filter(s=>s.status==='Booked'));const schedule=computed(()=>rows('payment_schedule').find(s=>s.id===selected.value)||rows('payment_schedule')[0]);const bookingFor=saleId=>rows('booking').find(b=>b.saleId===saleId);const templates=computed(()=>rows('schedule_template'));const who=id=>p.state.users.find(u=>u.id===id)?.name||'User';const today=()=>new Date().toISOString().slice(0,10);const req=v=>!!String(v??'').trim()||'Required';const expenses=computed(()=>p.state.expenses.filter(e=>e.tenantId===p.tenantId&&financeStatus(p.state,e)==='Approved'&&corporateBalance(p.state,e)>0));
const peopleFields=[['title','Title'],['fullName','Full name *'],['relation','Relationship (son / wife / daughter of)'],['relatedPerson','Related person'],['dob','Date of birth','date'],['phone','Contact number *'],['email','Email *','email'],['pan','PAN'],['aadhaar','Aadhaar'],['passport','Passport number'],['spouseName','Spouse name'],['spouseDob','Spouse DOB','date'],['anniversary','Anniversary','date'],['residentialAddress','Residential address'],['permanentAddress','Permanent address']];
const detailFields=[['enquiryNumber','Enquiry number'],['leadId','Lead ID'],['facing','Facing'],['floor','Floor'],['unitType','Unit type'],['areaSqft','Super built-up area (sq. ft.)'],['occupation','Occupation / business / profession'],['businessNature','Nature of business'],['company','Company'],['designation','Designation'],['channelPartnerName','Channel partner name'],['channelPartnerCompany','Channel partner company'],['referrerName','Referrer name'],['referrerProjectUnit','Referrer project / unit'],['referrerMobile','Referrer mobile'],['salesPerson','Sales person'],['relationshipManager','Relationship manager']];
async function photoChanged(value,key){const file=Array.isArray(value)?value[0]:value;if(!file){delete form.value.details[key].photo;return;}if(file.size>262144){error.value='Photo must be up to 256 KB.';return;}const reader=new FileReader();reader.onload=()=>{form.value.details[key].photo={name:file.name,base64:String(reader.result).split(',')[1]}};reader.readAsDataURL(file);}
const person=()=>Object.fromEntries(peopleFields.map(([k])=>[k,'']));
const pricing=()=>({gstBps:500,tdsBps:100,partA:[{label:'Basic price · rate × area',rupees:''},{label:'Premium location charges',rupees:'0'},{label:'Floor rise charges',rupees:'0'},{label:'Infrastructure charges',rupees:'0'},{label:'Car parking',rupees:'0'}],partB:[{label:'Clubhouse',rupees:'0',gstPercent:18},{label:'Maintenance · rate × area × months',rupees:'0',gstPercent:18},{label:'Legal charges',rupees:'0',gstPercent:18},{label:'Corpus fund',rupees:'0',gstPercent:0}]});
function priceData(v){return {gstBps:Math.round(Number(v.gstPercent)*100),tdsBps:Math.round(Number(v.tdsPercent)*100),partA:v.partA.map(l=>({label:l.label,amount:cents(l.rupees)})),partB:v.partB.map(l=>({label:l.label,amount:cents(l.rupees),gstBps:Math.round(Number(l.gstPercent)*100)}))};}
const quotedTotal=computed(()=>{try{return pricingTotals(priceData(form.value.pricing)).grandTotal}catch{return null}});
function open(k,d){error.value='';dialog.value=k;form.value={data:{}};
 if(k==='corporate_account')form.value=d?JSON.parse(JSON.stringify(d)):{number:'',bank:'',ifsc:'',label:'Payroll & administration',active:true,data:{}};
 if(k==='corporate_payment')form.value=d?{...JSON.parse(JSON.stringify(d)),paidRupees:String(d.paid/100),tdsRupees:String(d.tds/100)}:{expenseId:'',accountId:rows('corporate_account').find(a=>a.active)?.id||'',paidRupees:'',tdsRupees:'0',paidDate:today(),reference:'',data:{}};
 if(k==='booking'){const b=bookingFor(d.id);form.value=b?JSON.parse(JSON.stringify(b)):{saleId:d.id,unit:d.unit,bookingDate:d.date,wing:'',details:{applicant:{...person(),fullName:d.customer},coApplicant:person(),source:'',bookingPayments:[]},pricing:pricing(),data:{}};if(b){form.value.pricing.partA=b.pricing.partA.map(l=>({...l,rupees:String(l.amount/100)}));form.value.pricing.partB=b.pricing.partB.map(l=>({...l,rupees:String(l.amount/100),gstPercent:l.gstBps/100}));}else form.value.pricing.partA[0].rupees=String(Math.round(d.amount/1.05)/100);form.value.pricing.gstPercent=form.value.pricing.gstBps/100;form.value.pricing.tdsPercent=form.value.pricing.tdsBps/100;}
 if(k==='schedule_template')form.value={name:templates.value.at(-1)?.name||'Reference payment schedule',rows:JSON.parse(JSON.stringify(templates.value.at(-1)?.rows||referenceRows())),data:{}};
 if(k==='payment_schedule')form.value={bookingId:d.id,templateId:templates.value.at(-1)?.id||'',data:{}};
 if(k==='milestone')form.value={code:'excavation',wing:schedule.value?.wing||'',date:today(),note:'',data:{}};
 if(k==='demand')form.value={scheduleId:schedule.value.id,code:d.code,number:'DEM-'+(p.state.tenants.find(t=>t.id===p.tenantId)?.code||'UNIT')+'-'+String(rows('demand').length+1).padStart(3,'0'),accountId:p.state.reras.find(a=>a.tenantId===p.tenantId)?.id||'',data:{}};
 if(k==='receipt_allocation')form.value={demandId:d.id,receiptId:'',rupees:'',tdsRupees:'0',data:{}};
}
async function save(){try{error.value='';const d={...form.value,recordKind:dialog.value};if(dialog.value==='corporate_payment'){d.paid=cents(d.paidRupees);d.tds=cents(d.tdsRupees)}if(dialog.value==='booking'){d.pricing=priceData(d.pricing);}
 if(dialog.value==='schedule_template')d.rows=d.rows.map(r=>({...r,percent:Number(r.percent),delayDays:Number(r.delayDays)}));if(dialog.value==='receipt_allocation'){d.tds=cents(d.tdsRupees);d.amount=cents(d.rupees)+d.tds;}
 const result=await p.execute('extension-save',d,'Saved '+dialog.value.replaceAll('_',' '),false);if(result)dialog.value='';}catch(e){error.value=e.message}}
async function action(d,a){await p.execute('extension-transition',{id:d.id,action:a},'Approval recorded',false)}
const approveLabel=d=>approvalStageLabel(approvalStage(p.state,p.user,p.tenantId,d,p.state.extensionEvents.map(e=>({...e,amendmentId:e.documentId})),d.kind));const actions=d=>['submit','review','approve','reject'].filter(a=>canExtensionAct(p.state,p.user,p.tenantId,d,a));
const milestones=computed(()=>[...new Map([...templates.value.flatMap(t=>t.rows||[]).filter(r=>r.trigger==='milestone'),{code:'possession',label:'Possession'}].map(r=>[r.code,{title:r.label,value:r.code}])).values()]);
function print(){window.print()}
</script>
<template>
<template v-if="page==='corporate'"><div class="workflow-banner"><v-icon color="primary">mdi-bank-outline</v-icon><div><strong>Company-wide corporate accounts</strong><p>Unique across corporate and RERA accounts in every project. Pay approved salary, consultant and administration expenses.</p></div></div><section class="panel"><div class="panel-top"><h2>Corporate account registry</h2><v-btn v-if="user.superuser" color="primary" @click="open('corporate_account')">Register corporate account</v-btn></div><div class="detail-content"><div v-for="a in rows('corporate_account')" :key="a.id" class="queue-row"><div><strong>{{a.label}}</strong><p>{{a.bank}} · {{a.number}} · {{a.ifsc}}</p><span class="role-pill">{{a.active?'Active':'Archived · number reserved'}}</span></div><v-btn v-if="user.superuser" variant="outlined" @click="open('corporate_account',a)">Edit / archive</v-btn></div><p v-if="!rows('corporate_account').length" class="empty-state">Register at least one corporate account before recording salary or admin payments.</p></div></section><section class="panel mt-6"><div class="panel-top"><div><h2>Salary &amp; admin payments</h2><p>Payments settle approved expenses; project costs are recorded once in Expenses.</p></div><v-btn v-if="editable('corporate_payment')" color="primary" @click="open('corporate_payment')">Record corporate payment</v-btn></div><div class="table-scroll"><table class="orders-table"><thead><tr><th>PAYEE / CATEGORY</th><th>ACCOUNT / REFERENCE</th><th>NET PAID</th><th>TDS</th><th>PAID DATE</th><th>STATUS / ACTION</th></tr></thead><tbody><tr v-for="d in rows('corporate_payment')" :key="d.id"><td>{{d.payee}}<span class="cell-secondary">{{d.category}} · {{d.description}}</span></td><td>{{rows('corporate_account').find(a=>a.id===d.accountId)?.label||'Restricted'}}<span class="cell-secondary">{{d.reference}}</span></td><td>{{money(d.paid)}}</td><td>{{money(d.tds)}}</td><td>{{d.paidDate}}</td><td><span class="status-badge amber">{{extStatus(state,d)}}</span><v-btn v-if="extStatus(state,d)==='Draft'&amp;&amp;editable('corporate_payment')&amp;&amp;(user.superuser||d.createdBy===user.id)" variant="text" size="small" @click="open('corporate_payment',d)">Edit draft</v-btn><v-btn v-for="a in actions(d)" :key="a" size="small" variant="text" @click="action(d,a)">{{a==='approve'?approveLabel(d):a}}</v-btn><div v-for="e in state.extensionEvents.filter(e=>e.documentId===d.id)" :key="e.id" class="cell-secondary">{{e.action}} {{e.stage}} · {{who(e.actorId)}}</div></td></tr><tr v-if="!rows('corporate_payment').length"><td colspan="6" class="empty-state">Approve an expense, then record its corporate payment.</td></tr></tbody></table></div></section></template>
<template v-else-if="page==='bookings'"><div class="workflow-banner"><v-icon color="primary">mdi-account-details-outline</v-icon><div><strong>CRM booking profiles</strong><p>Applicant and co-applicant information, enquiry sources, unit particulars and sale pricing from your booking reference.</p></div></div><section class="panel"><div class="panel-top"><div><h2>Booked units &amp; applicants</h2><p>Create a Booked unit in CRM dashboard → Unit sales, then complete its profile here.</p></div></div><div class="table-scroll"><table class="orders-table"><thead><tr><th>UNIT / CUSTOMER</th><th>BOOKING DATE</th><th>SALE VALUE</th><th>PROFILE</th><th>SCHEDULE</th></tr></thead><tbody><tr v-for="s in sales" :key="s.id"><td>{{s.unit}}<span class="cell-secondary">{{s.customer}}</span></td><td>{{s.date}}</td><td>{{money(s.amount)}}</td><td><v-btn v-if="editable('booking')" variant="outlined" size="small" @click="open('booking',s)">{{bookingFor(s.id)?'Edit booking':'Complete booking'}}</v-btn><v-btn v-if="bookingFor(s.id)" variant="text" size="small" @click="showProfile=bookingFor(s.id)">View profile</v-btn></td><td><span v-if="rows('payment_schedule').some(x=>x.saleId===s.id)" class="role-pill">Schedule generated</span><v-btn v-else-if="bookingFor(s.id)&&editable('payment_schedule')" size="small" color="primary" @click="open('payment_schedule',bookingFor(s.id))">Generate schedule</v-btn><span v-else class="small muted">Complete booking first</span></td></tr></tbody></table></div></section></template>
<template v-else><div class="workflow-banner"><v-icon color="primary">mdi-calendar-clock-outline</v-icon><div><strong>Payment schedules &amp; demands</strong><p>Part A instalments use the pre-GST sale consideration. GST and TDS are separate; Part B falls due at possession.</p></div></div><div class="d-flex ga-3 mb-5"><v-btn variant="outlined" @click="activeTab='schedule'">Unit schedules</v-btn><v-btn variant="outlined" @click="activeTab='demands'">Demand register</v-btn><v-btn v-if="editable('milestone')" variant="outlined" @click="open('milestone')">Record milestone</v-btn><v-btn v-if="user.superuser" variant="outlined" @click="open('schedule_template')">Configure schedule</v-btn></div><template v-if="activeTab==='schedule'"><section class="panel"><div class="panel-top"><h2>Unit payment schedule</h2><span class="quiet-label">{{schedule?.unit}} · {{schedule?.wing}}</span></div><div class="table-toolbar"><v-select v-model="selected" :model-value="schedule?.id" :items="rows('payment_schedule').map(s=>({title:s.unit+' · '+s.wing,value:s.id}))" label="Sold unit" hide-details/></div><div v-if="schedule" class="table-scroll"><table class="orders-table"><thead><tr><th>INSTALMENT</th><th>% PART A</th><th>BASE VALUE</th><th>GST</th><th>TDS</th><th>NET RECEIVABLE</th><th>DUE DATE</th><th>DEMAND</th></tr></thead><tbody><tr v-for="r in schedule.rows" :key="r.code"><td>{{r.label}}</td><td>{{r.percent==null?'Part B':r.percent+'%'}}</td><td>{{money(r.base)}}</td><td>{{money(r.gst)}}</td><td>{{money(r.tds)}}</td><td><strong>{{money(r.net)}}</strong></td><td>{{dueDate(state,schedule,r)||'Awaiting completion'}}</td><td><span v-if="rows('demand').some(d=>d.scheduleId===schedule.id&&d.code===r.code&&extStatus(state,d)!=='Rejected')" class="role-pill">{{extStatus(state,rows('demand').find(d=>d.scheduleId===schedule.id&&d.code===r.code&&extStatus(state,d)!=='Rejected'))}}</span><v-btn v-else-if="editable('demand')&&dueDate(state,schedule,r)&&r.gross>0" variant="outlined" size="small" @click="open('demand',r)">Raise demand</v-btn></td></tr></tbody></table><div class="detail-content"><strong>Total sale value {{money(schedule.totals?.grandTotal)}}</strong><p class="small muted">Amounts are retained from the booking and template version {{schedule.templateVersion}}. Final Part A instalment reconciles rounding. Payments already received can be allocated to approved demands.</p></div></div><p v-else class="empty-state">Complete a CRM booking profile and generate its schedule in Bookings.</p></section><section class="panel mt-6"><div class="panel-top"><h2>Milestone completion history</h2></div><div class="detail-content"><div v-for="m in rows('milestone').slice().reverse()" :key="m.id" class="queue-row"><strong>{{m.code}} · {{m.wing||'Project-wide'}}</strong><span>{{m.date}} · {{m.note}} · {{who(m.createdBy)}}</span></div><p class="small muted">Latest entry for the matching wing takes precedence over project-wide completion. Date corrections affect unraised instalments; existing demands retain their due dates.</p></div></section></template><section v-else class="panel"><div class="panel-top"><h2>Demand register</h2></div><div class="table-scroll"><table class="orders-table"><thead><tr><th>DEMAND / UNIT</th><th>INSTALMENT</th><th>DUE DATE</th><th>GROSS / TDS</th><th>BALANCE</th><th>APPROVALS / RECEIPTS</th></tr></thead><tbody><tr v-for="d in rows('demand').slice().reverse()" :key="d.id"><td>{{d.number}}<span class="cell-secondary">{{d.unit}} · {{d.customer}}</span></td><td>{{d.label}}</td><td>{{d.dueDate}}</td><td>{{money(d.gross)}}<span class="cell-secondary">TDS {{money(d.tds)}}</span></td><td>{{money(demandBalance(state,d))}}</td><td><span class="status-badge amber">{{extStatus(state,d)==='Approved'?'Issued':extStatus(state,d)}}</span><v-btn v-for="a in actions(d)" :key="a" size="small" variant="text" @click="action(d,a)">{{a==='approve'?approveLabel(d):a}}</v-btn><v-btn v-if="extStatus(state,d)==='Approved'" size="small" variant="text" @click="printDemand=d">View / print</v-btn><v-btn v-if="extStatus(state,d)==='Approved'&&editable('receipt_allocation')&&demandBalance(state,d)>0" size="small" variant="text" @click="open('receipt_allocation',d)">Allocate receipt</v-btn><div v-for="e in state.extensionEvents.filter(e=>e.documentId===d.id)" :key="e.id" class="cell-secondary">{{e.action}} {{e.stage}} · {{who(e.actorId)}}</div></td></tr><tr v-if="!rows('demand').length"><td colspan="6" class="empty-state">Raise a dated instalment from a unit schedule.</td></tr></tbody></table></div></section></template>
<v-alert v-if="failure" type="error" class="mt-5">{{failure}}</v-alert>
<v-dialog :model-value="!!dialog" @update:model-value="v=>{if(!v)dialog=''}" max-width="1000" scrollable><v-card><v-card-title class="dialog-title">{{dialog.replaceAll('_',' ')}}<v-btn icon="mdi-close" variant="text" @click="dialog=''"/></v-card-title><v-card-text><v-alert v-if="error||failure" type="error" class="mb-4">{{error||failure}}</v-alert><template v-if="dialog==='corporate_account'"><v-text-field v-model="form.number" :readonly="!!form.id" label="Account number *"/><v-text-field v-model="form.bank" label="Bank *"/><v-text-field v-model="form.ifsc" label="IFSC *"/><v-text-field v-model="form.label" label="Purpose / label *"/><v-switch v-model="form.active" label="Active"/><p class="small muted">Archived account numbers remain reserved. At least one active account must remain.</p></template><template v-if="dialog==='corporate_payment'"><v-select v-model="form.expenseId" :items="expenses.map(e=>({title:e.payee+' · '+e.category+' · balance '+money(corporateBalance(state,e)),value:e.id}))" label="Approved expense *"/><v-select v-model="form.accountId" :items="rows('corporate_account').filter(a=>a.active).map(a=>({title:a.label+' · '+a.number,value:a.id}))" label="Corporate account *"/><div class="form-two-columns"><v-text-field v-model="form.paidRupees" label="Net paid (₹) *"/><v-text-field v-model="form.tdsRupees" label="TDS (₹)"/><v-text-field v-model="form.paidDate" type="date" label="Paid date *"/><v-text-field v-model="form.reference" label="Bank payment reference *"/></div></template>
<template v-if="dialog==='booking'"><p class="dialog-context">{{form.unit}} · booked {{form.bookingDate}}</p><v-text-field v-model="form.wing" label="Wing / block *"/><div class="form-two-columns"><v-text-field v-for="[key,label] in detailFields" :key="key" v-model="form.details[key]" :label="label"/><v-combobox v-model="form.details.source" :items="['Online / Digital','Events','Outdoor media','Channel partner','Referral']" label="How did you hear about us? · choose or type"/></div><v-expansion-panels multiple :model-value="[0]"><v-expansion-panel v-for="[key,title] in [['applicant','Applicant'],['coApplicant','Co-applicant (optional)']]" :key="key" :title="title"><v-expansion-panel-text><v-file-input label="Passport photo · PNG / JPEG up to 256 KB" accept="image/png,image/jpeg" @update:model-value="v=>photoChanged(v,key)"/><img v-if="form.details[key].photo" :src="'data:image/jpeg;base64,'+form.details[key].photo.base64" alt="Applicant photo" style="width:90px;height:110px;object-fit:cover"/><div class="form-two-columns"><v-text-field v-for="[field,label,type] in peopleFields" :key="field" v-model="form.details[key][field]" :label="key==='coApplicant'?label.replace(' *',''):label" :type="type||'text'"/></div></v-expansion-panel-text></v-expansion-panel></v-expansion-panels><p class="config-heading mt-6">Part A · sale consideration before GST</p><div v-for="(l,i) in form.pricing.partA" :key="i" class="form-two-columns"><v-text-field v-model="l.label" label="Charge"/><v-text-field v-model="l.rupees" label="Amount (₹)"/></div><v-btn variant="text" @click="form.pricing.partA.push({label:'',rupees:'0'})">Add Part A charge</v-btn><div class="form-two-columns mt-4"><v-text-field v-model="form.pricing.gstPercent" label="Part A GST (%) · configurable" type="number"/><v-text-field v-model="form.pricing.tdsPercent" label="Part A TDS (%) · configurable" type="number"/></div><p class="config-heading">Part B · payable on possession</p><div v-for="(l,i) in form.pricing.partB" :key="i" class="form-two-columns"><v-text-field v-model="l.label" label="Charge"/><v-text-field v-model="l.rupees" label="Amount before GST (₹)"/><v-text-field v-model="l.gstPercent" label="GST (%)" type="number"/></div><v-btn variant="text" @click="form.pricing.partB.push({label:'',rupees:'0',gstPercent:0})">Add Part B charge</v-btn><div class="detail-total"><span>Booked sale value · Part A + GST + Part B</span><strong>{{money(quotedTotal)}}</strong><small>Saving updates the booked sale value before schedule generation. Rates shown are editable reference values.</small></div><p class="config-heading">Booking payment details</p><div v-for="(r,i) in form.details.bookingPayments" :key="i" class="purchase-line"><div class="form-two-columns"><v-select v-model="r.mode" :items="['Cheque','RTGS','NEFT','UPI','Cash','Other']" label="Payment mode"/><v-text-field v-model="r.reference" label="Cheque / transfer number"/><v-text-field v-model="r.bank" label="Bank"/><v-text-field v-model="r.amount" label="Amount (₹)"/><v-text-field v-model="r.date" label="Payment date" type="date"/></div><v-btn variant="text" @click="form.details.bookingPayments.splice(i,1)">Remove payment detail</v-btn></div><v-btn variant="outlined" @click="form.details.bookingPayments.push({mode:'Cheque',reference:'',bank:'',amount:'',date:today()})">Add booking payment detail</v-btn><p class="small muted mt-3">These details describe payment instruments. Confirm cleared money separately in CRM Cash collections; entering a cheque here does not create a receipt.</p></template>
<template v-if="dialog==='schedule_template'"><v-text-field v-model="form.name" label="Template name *"/><div v-for="(r,i) in form.rows" :key="i" class="purchase-line"><div class="form-two-columns"><v-text-field v-model="r.code" label="Unique milestone code"/><v-text-field v-model="r.label" label="Instalment label"/><v-text-field v-model="r.percent" label="Part A (%)" type="number"/><v-select v-model="r.trigger" :items="['booking','milestone']" label="Due trigger"/><v-text-field v-model="r.delayDays" label="Days after trigger" type="number"/></div><v-btn variant="text" @click="form.rows.splice(i,1)">Remove instalment</v-btn></div><v-btn variant="outlined" @click="form.rows.push({code:'stage_'+(form.rows.length+1),label:'',percent:1,trigger:'milestone',delayDays:15})">Add instalment</v-btn><p class="small muted mt-3">Part A percentages must total 100%. Part B possession charges are added separately. New versions apply to future unit schedules.</p></template>
<template v-if="dialog==='payment_schedule'"><v-select v-model="form.templateId" :items="templates.map(t=>({title:t.name+' · v'+t.version,value:t.id}))" label="Schedule template *"/><p class="small muted">Generating retains the booking price and template. Milestone completion drives the due dates.</p></template><template v-if="dialog==='milestone'"><v-select v-model="form.code" :items="milestones" label="Completed milestone *"/><v-text-field v-model="form.wing" label="Wing / block · leave blank for project-wide"/><v-text-field v-model="form.date" label="Completion date *" type="date"/><v-textarea v-model="form.note" label="Completion / correction note *" rows="2"/></template><template v-if="dialog==='demand'"><v-text-field v-model="form.number" label="Demand number *"/><v-select v-model="form.accountId" :items="state.reras.filter(a=>a.tenantId===tenantId).map(a=>({title:a.label+' · '+a.number,value:a.id}))" label="Receiving RERA account *"/><p class="small muted">This saves a demand draft. Issuing requires the existing financial approvals. Amounts and the due date are retained on creation.</p></template><template v-if="dialog==='receipt_allocation'"><v-select v-model="form.receiptId" :items="suiteRows(state,'collection',tenantId).filter(r=>r.saleId===rows('demand').find(d=>d.id===form.demandId)?.saleId).map(r=>({title:r.reference+' · '+money(r.amount),value:r.id}))" label="Confirmed CRM receipt *"/><v-text-field v-model="form.rupees" label="Allocate net cash (₹) *"/><v-text-field v-model="form.tdsRupees" label="Allocate TDS (₹)"/><p class="small muted">Allocating an existing receipt does not add another cash inflow.</p></template><MetaFields v-if="dialog" :state="state" :user="user" :tenant-id="tenantId" :form-id="dialog" :record="form"/></v-card-text><v-card-actions class="dialog-actions"><v-btn @click="dialog=''">Cancel</v-btn><v-spacer/><v-btn color="primary" :loading="busy" @click="save">{{dialog==='schedule_template'?'Publish template version':'Save'}}</v-btn></v-card-actions></v-card></v-dialog>
<v-dialog :model-value="!!showProfile" @update:model-value="v=>{if(!v)showProfile=null}" max-width="900" scrollable><v-card v-if="showProfile"><v-card-title class="dialog-title">Booking · {{showProfile.unit}}<v-btn icon="mdi-close" variant="text" @click="showProfile=null"/></v-card-title><v-card-text><div class="custom-data"><span v-for="(v,k) in showProfile.details" :key="k"><small>{{k}}</small><template v-if="typeof v==='object'"><div v-for="(value,key) in v" :key="key"><small>{{key}}</small> <img v-if="key==='photo'&amp;&amp;value?.base64" :src="'data:image/jpeg;base64,'+value.base64" alt="Applicant photo" style="width:90px;height:110px;object-fit:cover"/><span v-else>{{typeof value==='object'?Object.entries(value).filter(([k])=>k!=='base64').map(([k,v])=>k+': '+v).join(' · '):value||'—'}}</span></div></template><strong v-else>{{v||'—'}}</strong></span></div><p class="mt-5">Sale value {{money(showProfile.amount)}} · {{showProfile.bookingDate}}</p></v-card-text></v-card></v-dialog>
<v-dialog :model-value="!!printDemand" @update:model-value="v=>{if(!v)printDemand=null}" max-width="800"><v-card v-if="printDemand" class="demand-print"><v-card-title class="dialog-title">VRISE · Payment demand<v-btn icon="mdi-close" variant="text" class="no-print" @click="printDemand=null"/></v-card-title><v-card-text><p>{{state.tenants.find(t=>t.id===tenantId)?.name}}</p><h2>{{printDemand.number}}</h2><p>{{printDemand.customer}} · Unit {{printDemand.unit}}</p><p class="mt-5">{{printDemand.label}} · due {{printDemand.dueDate}}</p><div class="custom-data"><span><small>Base amount</small><strong>{{money(printDemand.base)}}</strong></span><span><small>GST</small><strong>{{money(printDemand.gst)}}</strong></span><span><small>TDS</small><strong>{{money(printDemand.tds)}}</strong></span><span><small>Net receivable</small><strong>{{money(printDemand.net)}}</strong></span><span><small>Outstanding including TDS settlement</small><strong>{{money(demandBalance(state,printDemand))}}</strong></span></div><p class="mt-5">Pay to {{printDemand.bank?.bank}} · {{printDemand.bank?.label}}<br/>Account {{printDemand.bank?.number}} · IFSC {{printDemand.bank?.ifsc}}</p><p class="small muted mt-5">Approved payment demand. Please reference the demand and unit number when recording the payment.</p></v-card-text><v-card-actions class="no-print"><v-btn color="primary" @click="print">Print / save PDF</v-btn></v-card-actions></v-card></v-dialog>
</template>
